mapper.select:
select rating_id, course_id, user_id, score, create_time, update_time
  from learning_course_rating
 where course_id = #{courseId} and user_id = #{userId}

select count(*) as ratingCount, ifnull(sum(score), 0) as ratingScore
  from learning_course_rating
 where course_id = #{courseId}
